    data = np.random.rand(10, 10)
    def raw_indexing_method(key):
        return data[key]

    key = (np.array([], dtype=int), slice(None))

    class MockArray:
        def __init__(self, shape):
            self.shape = shape
        def __getitem__(self, key):
            return np.zeros(key)

    array = MockArray((10, 10))

    try:
        explicit_indexing_adapter(
            key,
            array,
            raw_indexing_method,
