    print("Testing OUTER_1VECTOR indexing...")
    data = np.random.rand(10, 10)
    def raw_indexing_method(key):
        return data[key]

    # Empty list for first dimension, valid for second
    key = (np.array([], dtype=int), np.array([1, 2], dtype=int))

    class MockArray:
        def __init__(self, shape):
            self.shape = shape
        def __getitem__(self, key):
            return np.zeros(key)

    array = MockArray((10, 10))

    try:
        explicit_indexing_adapter(
            key,
            array,
            raw_indexing_method,
            {},
            IndexingSupport.OUTER_1VECTOR,
            None,
            None
        )
        print("OUTER_1VECTOR indexing succeeded")
    except Exception as e:
        print(f"OUTER_1VECTOR indexing failed: {e}")
        raise e

if __name__ == "__main__":
    test_basic_indexing()
    test_outer_1vector_indexing()

